// The head's edge of a base item, model units; false: none known (an orb, a claw, an edged weapon whose head did not read off its model, an item not in the table).
inline const Row* RowOf(uint32_t code) {
    for (const Row& r : kRows)
        if (r.code == code) return &r;
    return nullptr;
}
inline bool Find(uint32_t code, float* head) {
    const Row* r = RowOf(code);
    if (!r) return false;
    *head = r->head;
    return true;
}

